\u0027\u0065\u0055\u0039\u0053\u0042\u0041\u0070\u006f\u003b\u0061\u0062\u0077\u0034\u0057\u0020\u0048\u0058\u005a\u006a\u0029\u0066\u0069\u006b\u005d\u003e\u0038\u003b\u003d\u002a\u0042\u0066\u0029\u0047\u0047\u0030\u006f\u007b\u0069\u0045\u007d\u004f\u007d\u003e\u007a\u007b\u0038\u007d\u0073\u002d\u0037\u006f\u0043\u0077\u0053\u004d\u0033\u002f\u0068\u0076\u0039\u0042\u0050\u0058\u0028\u0071\u0044\u0035\u0034\u0022\u0053\u0024\u0050\u0022\u0038\u006d\u004a\u0067\u0032\u0076\u005d\u003f\u0069\u007e\u0073\u0075\u0056\u0039\u0047\u005f\u0045\u007a\u002b\u003b\u0047\u0046\u0050\u0049\u0035\u0037\u006c\u0065\u0046\u0046\u002f\u0023\u007b\u0059\u0055\u0070\u0075\u0058\u0025\u0020\u0025\u0032\u0073\u0062\u0044\u0030\u0021\u0032\u002a\u0026\u002b\u0066\u005e\u007e\u0036\u0048\u0041\u002e\u0067\u0079\u0054\u0064\u004e\u0030\u0069\u002a\u0063\u0050\u003a\u0071\u0041\u0045\u0046\u006a\u003f\u0039\u006e\u002d\u003c\u002b\u0028\u004c\u0042\u005c\u007d\u007c\u006c\u0074\u0068\u0031\u0047\u006b\u0028\u0048\u003d\u0065\u006f\u0054\u0058\u0029\u0026\u002e\u0033\u0069\u0067\u004e\u0052\u007d\u006b\u0049\u003a\u005a\u0034\u006f\u004e\u0052\u0025\u0062\u007d\u0043\u002a\u003b\u0057\u0074\u003e\u0029\u0074\u005c\u0036\u0039\u0074\u002f\u005a\u0053\u0072\u003c\u005a\u0042\u0045\u0070\u0024\u0022\u0072\u002a\u0057\u0063\u0040\u0059\u0078\u007e\u0064\u006d\u0020\u0043\u006e\u0062\u0070\u004d\u0027\u0029\u0079\u003d\u0062\u006b\u0042\u0056\u0060\u004f\u0079\u0062\u0025\u0061\u002d\u005f\u0029\u0037\u0034\u0023\u0055\u002c\u0024\u0078\u003a\u0030\u0032\u006d\u0020\u0050\u0030\u0061\u006f\u0079\u0024\u0068\u0062\u0048\u0077\u0063\u0039\u002a\u002e\u0025\u0057\u006b\u003b\u004d\u003a\u007a\u004f\u004a\u003e\u0065\u0056\u0028\u004f\u003f\u006f\u0068\u003f\u004e\u003c\u0073\u006e\u002f\u006a\u006b\u0040\u007b\u0052\u003e\u002a\u0022\u0028\u0062\u0056\u0026\u0033\u0053\u0051\u0041\u0034\u003b\u006f\u0076\u0031\u006c\u0063\u0051\u0051\u0072\u006f\u0065\u007e\u006b\u004c\u0025\u0067\u002f\u0033\u0056\u006b\u003a\u002b\u0026\u004f\u0059\u004d\u005f\u0033\u004b\u002b\u0037\u005e\u007b\u003e\u004b\u005b\u004b\u0052\u0021\u0053\u003d\u0060\u0047\u006d\u005e\u0031\u0032\u0059\u0055\u002c\u007a\u004e\u0049\u0070\u0036\u0071\u004f\u0048\u0068\u0068\u004b\u0037\u0042\u0034\u0074\u005e\u006a\u003f\u004f\u0052\u005d\u0057\u006e\u007d\u006b\u0071\u0079\u0032\u0067\u0075\u003f\u0026\u004a\u005b\u0036\u002f\u0039\u004e\u0044\u003b\u0070\u0027\u004d\u0020\u0078\u0024\u0021\u007b\u0055\u004a\u0072\u006b\u0038\u0022\u0027\u007c\u0067\u0064\u005c\u005f\u0041\u005c\u0041\u0073\u0024\u0049\u0020\u0073\u0048\u004f\u0070\u003d\u0038\u0045\u002c\u005c\u007d\u0034\u0030\u0074\u0034\u007a\u0037\u0069\u0049\u0074\u0034\u004f\u007b\u0021\u004a\u0034\u005e\u004b\u0023\u002c\u007c\u006b\u0079\u0078\u0056\u0049\u0056\u0041\u0067\u003d\u0042\u0079\u0028\u0044\u0031\u007d\u003c\u0043\u0036\u0021\u0072\u003c\u0023\u0032\u004d\u0042\u0042\u0078\u0020\u0027\u0055\u004f\u0040\u0068\u005e\u0079\u003a\u006e\u0068\u0035\u0049\u0072\u0070\u0049\u002e\u0067\u0027\u006d\u0022\u0076\u0047\u0075\u0036\u007d\u005d\u0026\u0039\u006f\u002e\u0039\u002b\u0070\u002d\u0040\u0060\u005c\u006c\u007e\u0044\u0047\u006e\u0052\u003a\u0032\u004a\u006c\u005d\u006c\u007b\u0024\u006f\u0061\u0055\u0065\u0056\u0025\u0022\u004f\u0061\u0031\u0034\u002e\u0052\u0020\u0058\u0047\u006b\u0026\u0032\u0036\u0047\u0049\u0023\u0033\u002a\u0051\u002e\u003c\u0062\u002d\u0063\u0043\u006f\u006d\u003f\u0022\u005b\u002c\u0036\u0036\u006a\u0070\u005c\u004f\u002b\u004b\u0042\u003d\u0076\u0023\u0033\u0076\u0026\u006c\u0061\u005d\u0056\u0072\u0045\u003e\u0036\u0026\u0036\u006f\u0076\u0033\u0021\u0024\u002d\u0043\u0046\u003a\u0079\u002e\u0060\u003c\u006d\u0026\u0044\u0034\u005b\u0047\u0048\u0032\u0078\u0037\u0054\u002f\u007d\u0060\u0035\u0037\u005e\u0043\u0053\u0074\u006b\u004c\u0063\u0055\u005e\u0025\u002d\u0044\u005d\u003e\u0040\u005b\u002d\u0031\u0060\u0067\u0042\u003e\u0056\u007e\u004e\u005f\u003a\u007d\u005f\u0067\u004c\u0075\u002f\u0040\u003b\u0023\u0078\u0052\u0069\u005a\u0028\u006b\u002a\u0057\u0057\u0050\u0031\u0024\u0030\u005c\u0047\u0068\u0070\u0031\u002f\u0055\u003e\u0077\u0049\u0036\u0031\u007a\u0038\u003a\u0021\u0064\u0057\u003a\u0056\u0054\u002d\u005a\u0029\u0059\u0053\u0027\u0070\u005f\u005c\u0034\u0059\u004b\u0036\u0071\u006b\u0056\u0068\u003a\u0051\u006e\u0038\u006a\u004f\u0057\u0045\u007d\u003d\u007c\u0071\u0034\u0034\u0032\u004f\u0051\u0043\u0065\u0076\u0059\u006f\u0035\u007a\u0021\u0074\u0072\u0063\u0046\u0067\u0077\u0077\u003c\u0024\u002a\u0065\u003c\u002c\u006c\u0020\u007e\u0051\u005b\u007c\u0057\u004f\u003b\u0077\u003f\u0054\u0069\u005a\u002d\u004a\u0044\u0034\u0059\u0055\u0058\u0062\u0052\u007d\u0029\u0027\u0065\u0026\u005e\u003c\u003c\u0028\u0047\u006b\u003b\u0038\u006c\u004c\u0076\u0059\u0023\u0045\u007b\u0074\u0073\u002e\u0060\u007d\u0075\u005f\u002c\u006c\u0020\u007c\u005e\u0065\u005a\u005f\u0067\u006e\u0034\u0044\u0079\u0042\u004d\u004c\u006d\u0034\u0054\u0079\u0031\u004f\u004b\u0067\u0073\u0020\u004e\u0041\u004a\u003b\u0035\u003f\u0041\u0043\u002a\u0038\u0067\u0073\u0028\u0046\u005f\u007d\u0060\u0026\u004b\u0069\u0079\u004f\u0075\u0062\u0051\u003e\u0031\u0066\u003d\u0037\u003a\u0050\u0063\u003f\u0053\u0062\u0040\u0027\u005f\u0062\u0032\u0029\u007c\u0038\u0069\u002c\u0024\u007a\u0024\u0039\u0042\u0022\u0025\u002f\u007a\u0065\u0042\u0049\u0033\u0046\u0035\u007b\u002e\u0041\u005f\u0040\u007b\u0072\u0076\u004d\u004e\u004f\u0031\u005b\u0069\u003b\u005f\u007d\u005f\u0051\u004e\u0041\u002d\u0061\u003c\u0024\u006e\u004c\u0060\u0027\u005f\u007e\u002a\u003f\u0078\u002a\u0075\u005f\u0048\u0071\u0074\u007e\u007b\u0032\u003a\u0046\u004d\u007d\u0048\u0037\u0040\u004c\u006b\u0062\u0020\u0060\u0056\u0051\u006c\u0070\u003f\u0038\u0057\u0076\u007a\u0035\u0035\u003c\u0067\u0035\u006e\u0060\u0058\u007d\u004f\u004f\u0030\u004e\u0034\u0069\u0059\u003a\u0067\u002d\u0039\u0023\u0075\u0071\u0073\u002c\u0064\u0066\u0041\u0072\u0064\u006f\u0034\u0040\u0040\u007d\u0069\u0032\u003f\u0047\u0037\u0054\u005c\u002e\u003c\u0031\u0066\u005c\u0028\u007d\u0059\u004f\u0043\u0077\u0024\u0040\u0043\u006e\u0027\u004b\u0062\u0064\u004e\u003f\u0023\u0053\u0044\u005f\u005f\u0073\u0023\u007e\u005e\u0059\u0043\u005e\u0050\u0052\u006f\u0043\u007c\u003c\u002c\u002f\u0066\u0070\u0076\u0075\u0021\u0043\u0049\u007e\u0042\u0037\u0056\u002f\u006d\u0062\u0032\u0063\u003d\u0044\u005c\u0050\u002c\u0045\u005a\u0035\u007a\u0066\u0023\u0058\u0076\u007a\u0032\u0035\u0070\u003f\u0074\u005c\u0058\u0079\u0078\u003d\u007e\u0047\u005e\u0074\u006d\u0057\u0041\u003a\u0038\u0067\u0022\u0055\u004e\u0036\u0038\u0054\u0057\u0057\u0028\u0031\u0076\u0041\u0025\u005f\u0047\u0032\u004c\u002f\u002d\u0065\u004c\u003f\u006d\u0033\u0070\u0049\u0043\u0057\u0077\u0034\u0072\u005a\u0062\u003b\u004e\u003d\u002f\u0063\u006b\u0069\u006b\u0047\u0022\u0068\u0024\u006c\u003b\u0075\u0039\u0063\u007a\u005c\u0053\u0075\u003f\u0061\u0079\u004d\u002d\u0026\u0027\u0058\u006f\u0061\u002f\u0052\u0039\u0055\u0056\u0038\u0035\u0046\u0038\u0035\u007e\u0077\u0079\u0078\u0052\u0071\u003b\u002c\u0079\u0047\u005c\u0076\u0032\u0027\u005a\u0046\u0021\u003b\u004e\u0069\u0073\u0076\u0059\u0075\u0027\u002f\u0053\u007a\u003d\u0068\u002a\u0058\u005f\u0028\u006c\u0038\u005f\u006b\u0031\u0040\u004f\u0059\u003b\u0028\u005b\u002b\u0035\u003c\u003e\u0076\u0047\u0069\u0075\u0071\u0040\u0031\u0027\u0073\u0032\u0055\u0067\u003e\u0079\u0059\u005c\u0047\u0033\u0062\u0039\u003c\u003d\u003c\u004e\u006e\u0071\u003e\u006c\u002b\u0021\u003b\u0061\u0032\u0059\u0056\u0065\u006c\u006a\u0029\u0075\u0029\u0059\u004b\u0070\u006d\u0030\u003e\u0025\u0078\u0063\u0061\u0042\u003c\u0045\u0021\u004b\u002c\u0061\u0046\u0027\u0055\u0056\u0063\u003f\u0036\u007d\u0044\u0033\u0067\u0063\u0050\u003f\u0044\u0025\u0061\u0071\u0064\u0064\u0027\u0061\u0048\u0020\u0062\u0055\u0048\u0063\u0069\u003f\u0055\u0054\u0021\u0042\u0062\u0059\u0059\u007e\u0070\u006a\u0076\u002c\u0062\u004f\u004b\u0033\u0047\u0038\u0050\u003b\u004d\u005a\u003d\u005c\u0049\u0048\u0067\u004a\u004f\u0056\u006e\u0054\u005b\u002d\u0056\u0031\u007d\u0079\u0047\u0067\u0077\u004d\u0076\u0066\u007d\u007d\u0055\u0040\u0059\u0061\u0078\u0039\u0066\u003a\u0038\u003d\u0074\u003a\u0047\u0064\u0022\u0060\u004c\u0053\u0079\u0050\u0040\u0070\u0045\u0026\u007d\u002f\u006b\u0075\u004c\u0039\u003a\u0039\u005d\u0047\u0069\u0059\u0052\u0059\u0045\u0033\u002f\u0025\u0062\u0056\u0063\u0056\u006c\u0032\u0059\u0050\u002b\u004d\u0068\u0047\u005b\u0056\u003c\u0068\u0046\u0054\u0078\u006d\u0079\u0044\u0049\u0052\u0060\u002d\u0032\u0042\u0023\u002c\u003c\u0063\u0029\u0062\u0065\u0075\u0055\u0062\u0054\u0065\u0068\u007d\u005c\u0023\u006f\u005b\u003f\u0048\u0021\u0065\u005d\u003f\u004b\u0024\u005a\u006e\u0070\u004a\u0047\u003f\u002f\u0077\u0061\u007b\u003c\u0031\u002e\u0044\u0032\u0043\u0045\u004c\u0051\u0077\u007b\u003c\u0025\u0045\u0077\u0061\u004d\u0065\u0038\u007e\u0048\u0033\u004d\u0078\u0051\u0055\u0060\u0057\u0046\u005f\u002b\u005a\u0060\u0038\u0072\u0075\u007a\u004a\u0037\u003c\u0029\u0073\u0071\u007e\u0055\u007e\u007e\u0030\u003b\u0030\u003f\u0026\u0028\u005e\u003b\u004d\u006b\u007a\u005c\u0032\u0047\u005e\u002e\u0056\u0024\u0050\u0049\u0061\u005f\u005d\u003f\u0062\u0069\u006e\u0065\u0071\u0073\u0074\u0028\u0048\u0021\u0055\u0024\u0033\u002f\u003c\u0039\u0051\u0034\u0041\u007c\u004b\u005f\u0032\u0028\u0041\u003e\u007b\u0077\u0033\u004d\u004e\u0064\u005b\u0068\u0078\u005e\u007d\u006f\u0065\u005e\u006b\u0065\u005a\u0023\u007e\u004c\u004f\u0048\u007e\u0062\u006e\u0071\u0051\u0072\u0033\u0063\u0057\u002e\u004a\u0043\u0021\u003a\u007e\u0056\u003c\u0035\u005b\u006d\u0032\u0073\u003d\u0067\u002a\u006f\u0078\u0037\u007a\u0042\u0044\u0071\u002d\u007a\u0021\u0036\u005b\u0027\u0070\u0075\u0039\u0035\u003b\u003e\u006a\u0020\u002c\u005f\u0061\u0076\u007e\u0037\u007d\u0050\u0049\u0077\u003c\u005a\u0054\u003b\u0057\u003e\u0041\u0076\u0054\u0066\u0022\u0072\u0060\u006f\u0056\u0036\u0030\u006d\u0049\u002e\u0073\u003f\u0033\u0047\u006d\u003c\u0026\u0063\u0046\u0055\u0065\u0069\u0072\u0032\u0049\u0078\u006b\u006c\u0074\u003a\u0033\u0024\u006f\u0056\u007e\u0021\u007b\u0065\u0071\u0033\u002b\u0056\u0069\u0031\u007d\u0071\u005b\u0061\u004b\u007e\u0052\u002f\u0048\u003e\u0032\u004f\u0044\u006a\u0021\u004a\u0064\u0058\u0028\u003d\u003c\u0049\u0044\u0046\u0039\u005d\u007e\u0060\u003a\u006e\u0032\u0067\u005a\u0079\u0048\u0050\u006f\u0048\u005a\u004e\u0057\u0042\u003c\u0032\u004a\u0062\u0050\u005e\u0065\u0042\u0050\u0070\u0035\u0031\u0023\u007d\u0056\u003c\u004b\u0047\u006d\u004a\u0052\u003b\u0035\u0063\u0054\u0050\u0063\u0051\u0027\u0073\u0025\u002d\u0046\u0036\u0055\u0063\u005e\u0068\u0052\u002f\u0058\u006a\u0043\u0051\u0023\u005c\u004a\u0037\u0054\u0055\u0079\u0032\u006b\u003f\u005f\u004b\u002f\u0047\u0070\u005e\u0061\u0043\u0059\u0065\u005d\u0034\u004e\u003b\u0061\u0036\u002b\u003f\u0041\u0050\u0076\u0038\u0076\u0039\u0058\u0069\u003d\u0023\u0061\u006e\u004a\u007a\u004d\u0076\u0041\u0068\u0047\u006d\u0054\u0070\u0034\u0044\u0041\u0079\u0049\u0069\u007b\u006b\u0050\u002c\u003a\u004c\u0060\u0070\u005a\u0033\u0051\u006a\u0048\u0064\u0075\u004e\u0052\u006d\u0067\u0057\u0033\u0048\u0045\u003a\u0051\u006c\u005f\u006b\u0055\u0072\u004c\u0050\u0056\u002b\u0043\u007e\u0066\u0079\u002e\u0043\u0046\u0067\u005d\u002a\u0037\u004b\u0051\u002c\u0046\u0020\u0026\u0050\u002e\u0046\u0050\u004a\u004c\u005c\u0029\u0025\u002e\u0050\u0049\u0060\u0020\u0021\u004b\u0060\u0031\u0042\u004f\u0046\u0037\u0040\u0056\u006f\u0022\u0047\u0023\u003a\u0076\u0028\u0078\u0040\u002a\u0023\u004a\u002a\u004a\u004c\u0046\u0048\u0036\u006e\u0047\u004d\u003d\u0077\u0072\u0042\u003f\u006e\u004e\u0046\u006f\u006a\u006c\u006c\u007b\u0049\u005c\u0021\u005d\u004e\u0076\u0041\u002d\u005c\u007d\u006b\u003b\u006c\u006a\u0056\u0076\u0051\u002b\u0063\u0050\u0056\u004e\u0063\u006e\u0031\u007e\u002f\u0056\u002d\u0060\u002b\u0078\u0034\u005f\u007b\u0039\u004f\u0045\u0055\u0075\u0060\u004a\u003c\u002b\u0058\u0063\u0024\u0075\u0071\u0046\u004f\u0060\u006c\u002e\u005d\u0064\u0036\u0027\u0048\u0023\u004f\u004a\u0050\u0038\u005d\u0047\u007d\u0035\u005b\u0076\u0071\u0058\u006d\u007e\u004e\u0021\u0049\u0035\u0041\u0037\u0023\u0024\u0029\u005e\u006e\u004c\u002c\u006f\u0068\u0040\u0068\u0072\u0037\u005a\u006d\u0073\u0028\u006e\u003d\u006b\u0065\u0076\u0069\u006e\u0072\u006d\u0047\u0049\u003e\u0038\u0036\u0033\u0074\u0052\u006a\u005c\u0043\u0040\u0079\u002f\u0075\u004a\u0076\u0032\u0073\u004c\u003b\u0078\u0034\u0065\u004c\u0053\u006f\u003e\u0065\u004c\u0039\u0051\u002e\u0062\u0076\u007c\u002e\u0060\u0059\u0056\u0061\u0047\u003b\u002d\u0064\u0025\u0056\u0035\u0061\u006e\u0079\u0075\u007d\u0072\u0025\u004c\u003b\u006c\u0027\u0036\u0036\u0047\u0079\u005f\u0078\u0020\u0028\u0030\u002d\u0035\u0077\u003b\u0067\u0064\u0079\u0031\u007a\u002c\u006b\u005d\u0071\u003b\u0021\u0065\u004d\u002b\u006c\u0078\u0024\u0077\u0060\u0052\u004f\u003b\u0076\u0020\u006f\u0040\u004f\u007b\u007e\u0047\u0078\u002b\u004d\u0075\u0070\u0047\u0047\u003e\u0067\u0068\u0031\u0035\u0054\u0071\u0036\u0021\u007a\u0022\u0058\u0028\u005a\u0051\u0035\u0077\u0072\u005e\u0045\u006d\u0051\u005e\u003c\u006f\u006f\u0079\u0030\u003b\u0062\u002f\u004f\u0028\u003a\u0031\u0079\u0058\u0021\u0026\u007d\u0068\u002c\u006a\u0027\u007c\u004c\u005e\u0077\u0076\u0020\u007d\u007b\u0039\u003e\u007a\u007a\u0025\u007b\u0022\u0026\u002e\u0026\u007b\u002a\u003a\u0058\u0056\u0068\u003f\u0033\u007a\u0040\u0071\u004d\u0042\u0031\u0070\u0067\u003a\u003a\u0055\u0065\u0069\u006e\u0040\u0056\u006e\u0036\u0055\u0050\u0058\u0056\u002f\u004f\u0064\u003b\u0073\u0026\u002a\u005e\u0042\u0042\u0033\u0075\u0053\u0039\u0028\u0034\u0058\u0060\u0076\u0056\u0029\u0072\u004c\u0034\u0078\u0074\u0059\u0050\u0064\u004f\u006e\u002a\u0042\u005a\u004b\u006f\u0032\u0045\u002b\u006a\u0048\u0069\u0025\u0052\u0025\u007a\u0041\u004c\u0028\u0039\u005b\u0033\u0048\u0035\u0045\u003f\u0054\u007a\u0054\u002c\u002d\u0063\u0061\u0039\u004b\u0047\u0049\u005c\u0050\u0032\u0020\u007e\u0024\u006a\u0029\u003a\u0055\u004b\u0026\u0074\u0038\u002c\u0069\u0024\u005c\u0070\u005d\u006e\u0038\u007e\u0074\u003f\u0040\u0060\u004f\u005e\u005e\u006c\u0062\u006d\u0064\u006f\u005a\u004d\u0075\u002a\u0025\u0071\u0064\u0034\u005a\u002e\u003e\u0028\u005c\u0052\u0071\u003b\u002e\u0067\u0068\u0053\u002d\u0062\u0044\u0068\u0059\u0024\u004c\u0061\u006b\u006b\u0025\u0077\u003b\u0050\u0079\u0072\u0026\u002d\u0038\u0022\u006e\u0064\u0043\u0037\u004d\u0034\u0040\u0023\u005e\u006b\u0058\u0056\u0025\u003b\u002d\u0073\u0036\u0044\u0021\u0032\u0063\u003b\u0056\u0036\u0038\u0051\u0021\u0063\u0077\u0045\u0038\u0068\u0038\u005d\u0078\u0056\u0042\u0027\u003c\u0050\u0049\u003b\u0037\u0056\u005f\u0040\u0068\u0041\u0042\u002e\u007b\u0037\u006d\u0071\u0054\u004c\u0077\u0037\u0025\u0053\u0074\u006b\u0048\u0030\u0076\u005f\u006c\u0059\u002f\u002e\u0052\u0073\u005b\u0074\u0072\u002d\u0028\u0056\u0037\u002e\u007b\u0027\u0028\u0021\u004e\u0023\u0073\u0058\u004d\u0062\u0023\u002c\u0065\u0053\u0069\u0046\u0061\u0043\u0033\u005c\u005d\u0030\u007a\u0022\u0038\u0020\u0024\u0078\u0068\u007e\u0046\u0054\u0031\u002a\u0075\u0022\u0021\u0026\u0062\u0079\u0065\u003f\u005f\u003c\u0044\u006a\u0039\u0058\u0044\u003e\u0030\u007d\u005c\u002f\u007c\u003d\u0052\u004d\u0020\u0056\u0079\u0033\u0026\u003b\u004f\u0060\u002b\u005d\u004a\u0050\u004e\u0070\u004d\u003c\u007d\u006f\u002f\u0036\u0052\u0035\u005e\u005e\u006a\u0059\u007a\u0041\u0041\u0072\u0065\u006a\u0065\u0040\u0061\u004f\u0038\u0073\u0063\u0037\u006f\u004c\u002f\u0025\u004e\u0068\u0059\u0077\u0049\u0061\u0059\u0022\u0026\u0079\u005a\u0028\u0043\u004c\u0035\u007a\u0060\u004c\u002b\u0041\u0042\u007c\u0078\u005b\u004d\u0057\u0047\u0065\u0077\u0052\u0058\u007a\u0024\u005b\u002e\u0053\u0077\u0037\u0073\u005d\u0063\u005b\u0041\u002b\u0042\u0057\u002e\u0077\u0075\u002e\u0045\u0068\u0055\u0055\u0069\u0036\u0039\u0079\u0062\u0056\u0053\u0034\u0077\u0037\u0025\u0026\u0066\u0054\u0066\u0053\u006e\u004e\u0073\u0062\u0076\u002e\u0073\u0046\u004d\u005a\u0030\u0036\u003b\u005b\u0024\u0026\u0028\u0052\u0071\u0070\u0072\u0063\u0056\u0068\u0072\u005f\u005e\u005d\u0039\u003d\u007a\u0066\u006e\u005f\u005c\u0027\u0075\u0062\u004b\u002b\u0024\u006b\u002b\u0063\u0038\u006a\u007c\u0056\u0023\u0077\u0021\u007a\u0078\u0067\u0076\u007d\u0062\u0030\u006e\u0052\u004f\u0021\u0053\u004b\u0046\u004a\u003d\u0034\u0048\u0027\u007c\u0063\u0061\u0069\u0046\u0031\u0025\u0059\u002c\u007b\u0026\u003b\u0072\u0074\u002e\u0062\u0052\u0050\u0049\u0030\u0027\u0079\u0063\u005e\u0028\u0055\u0051\u0074\u0049\u005f\u0074\u007b\u002a\u0039\u0051\u005a\u0038\u003c\u0059\u0050\u0064\u0064\u0035\u0054\u0029\u006f\u0050\u002d\u0079\u0045\u007e\u0024\u0076\u0064\u0020\u002e\u004c\u0072\u0064\u004a\u0028\u0023\u0029\u0075\u003b\u006f\u003b\u0023\u0057\u006a\u0042\u0055\u002b\u003b\u003c\u0035\u0045\u0045\u0046\u0039\u0039\u004b\u003c\u0034\u0050\u006d\u0078\u002b\u0076\u0022\u0029\u0077\u0067\u006d\u0029\u0021\u0044\u004c\u0075\u004c\u004c\u0060\u0048\u005b\u0073\u006f\u002a\u0041\u0047\u0048\u006b\u0050\u005f\u004e\u0075\u003f\u0072\u0027\u004e\u0072\u0071\u002e\u003e\u007e\u0045\u0055\u006a\u002b\u0022\u0066\u006e\u0051\u0074\u003c\u005d\u0052\u0037\u0066\u0052\u003f\u003e\u0023\u005a\u003d\u005f\u0030\u003c\u007a\u002f\u0074\u005d\u002a\u0023\u0026\u0071\u004c\u006d\u0074\u0037\u003c\u0022\u005b\u002a\u004c\u0044\u0065\u0061\u0073\u0027\u0044\u006e\u007b\u002b\u0079\u002d\u0046\u002f\u0030\u0064\u0066\u0060\u0049\u0046\u005a\u0056\u0037\u007b\u007e\u0076\u0056\u0030\u0064\u002d\u0055\u0035\u0065\u0062\u006d\u0036\u005c\u0068\u0034\u003e\u004b\u0074\u002b\u004c\u0051\u007c\u0027\u0051\u005e\u0027\u0047\u0030\u0073\u0062\u0064\u0040\u0056\u0048\u005f\u0060\u002c\u006d\u0065\u0073\u0044\u0062\u004d\u003d\u006a\u0043\u004d\u006d\u007b\u0029\u0079\u005c\u0023\u0070\u004b\u0069\u0039\u0063\u007b\u0027\u003d\u0061\u003c\u006c\u0040\u0051\u0058\u0021\u0074\u0059\u004a\u002b\u0060\u0044\u003a\u0066\u0057\u0020\u0062\u007c\u0075\u0026\u002b\u003f\u0075\u0041\u0054\u004c\u0022\u007d\u0021\u0052\u0030\u003d\u006d\u006a\u0034\u0069\u0068\u006b\u0025\u0040\u0043\u0072\u003e\u0034\u004a\u004a\u006d\u0062\u0065\u0021\u0070\u0062\u0045\u0077\u0021\u0040\u0049\u0059\u004d\u0033\u0024\u0048\u0061\u0054\u0055\u0035\u0073\u0032\u0030\u0043\u004b\u003d\u0036\u0049\u0053\u0065\u0060\u0037\u0058\u007d\u0036\u0065\u0040\u0048\u0044\u0075\u0051\u0077\u0052\u0034\u002c\u004c\u0079\u0073\u0075\u005d\u0076\u0072\u0053\u003a\u007d\u0073\u0070\u006a\u0045\u0066\u005b\u0040\u0079\u0077\u0064\u005e\u004f\u0032\u0066\u0055\u0078\u005c\u006b\u004a\u0056\u007d\u0067\u0032\u0031\u0043\u0068\u0071\u0077\u002c\u007d\u0036\u004c\u005f\u0046\u0037\u006d\u007e\u0041\u0036\u003e\u002c\u0039\u005b\u002f\u004e\u002e\u0074\u0072\u0059\u0046\u0033\u0043\u0079\u004a\u0040\u005d\u0023\u0026\u002e\u003c\u0065\u0078\u0060\u0034\u0057\u0039\u004e\u0072\u0029\u0051\u0029\u0050\u0066\u0065\u005f\u0024\u0046\u0077\u0056\u0021\u0046\u002a\u0027\u0051\u006d\u005e\u0043\u0051\u0063\u003f\u0059\u005e\u0063\u0031\u0044\u0065\u0052\u0058\u003d\u0070\u004e\u0050\u0023\u004d\u007b\u0044\u003e\u0039\u004c\u007a\u002c\u0054\u006b\u0060\u005e\u0075\u002e\u0044\u0033\u0023\u0051\u0029\u0079\u002f\u0037\u002d\u002c\u004c\u007a\u0026\u003d\u002e\u005a\u0078\u0038\u0063\u0079\u0078\u0071\u0055\u0045\u004c\u002b\u0079\u005e\u002d\u0073\u0078\u006f\u0025\u0031\u002d\u005a\u007e\u0063\u0026\u007d\u0056\u005d\u0074\u0039\u004d\u007c\u0046\u0050\u0067\u0063\u0071\u0041\u004d\u0071\u005d\u0020\u004f\u006f\u0040\u003d\u006f\u0047\u0051\u0027\u0044\u0068\u0064\u0075\u0048\u0063\u0056\u0049\u0042\u0072\u0071\u0021\u0039\u0049\u0072\u0063\u0034\u0066\u004e\u0048\u005b\u0061\u0026\u0058\u0072\u0024\u005d\u002b\u0037\u002b\u0076\u0022\u0067\u0043\u0060\u003b\u003c\u0031\u004d\u0032\u0077\u0042\u0073\u0047\u007e\u002e\u0022\u0070\u0056\u0049\u007d\u0030\u0060\u0032\u003a\u0072\u0078\u0042\u0054\u0023\u0058\u005a\u002f\u0034\u0068\u006e\u0048\u007e\u0060\u0061\u002f\u007d\u0064\u006b\u0078\u0023\u003a\u0041\u0060\u007e\u0055\u0063\u0053\u0033\u007d\u006f\u0064\u002f\u005f\u0076\u0024\u0036\u0066\u007a\u0054\u004b\u006b\u003d\u0051\u004b\u0061\u0079\u0068\u0065\u0034\u0039\u0041\u0072\u0032\u0028\u0061\u0027\u0079\u003e\u002d\u005e\u004b\u0074\u0061\u0045\u007d\u0026\u0035\u0077\u0074\u0072\u0031\u004b\u002a\u0070\u003e\u0028\u004a\u002b\u0066\u0044\u0040\u0027\u0047\u0024\u005d\u006f\u005b\u0035\u003f\u0027\u003c\u004c\u0039\u0069\u006d\u004b\u0075\u0072\u0054\u0069\u0067\u0047\u0065\u0065\u003f\u0040\u004a\u005d\u006b\u007b\u0038\u003f\u005b\u005a\u0062\u0071\u0077\u004a\u0048\u0055\u0024\u0023\u0068\u004f\u0051\u006e\u006f\u0038\u005e\u0051\u003f\u0064\u0066\u007a\u0036\u0038\u0063\u004c\u0034\u0034\u0039\u003d\u0037\u0050\u0073\u0031\u0055\u0041\u0036\u0037\u0023\u0059\u0026\u0047\u0077\u0054\u0034\u0072\u0038\u0029\u004d\u0041\u0065\u0067\u0063\u006f\u0079\u003f\u0078\u004d\u0044\u0065\u004c\u0063\u0058\u003d\u0029\u0029\u0045\u0045\u0020\u0049\u0056\u004f\u0020\u005f\u005a\u005c\u0055\u0033\u0054\u0056\u0055\u0060\u0060\u0060\u0065\u0030\u0033\u0049\u004c\u003b\u0026\u002d\u0065\u003b\u0042\u0063\u004e\u0041\u003d\u0022\u006c\u0028\u0048\u0035\u0027\u0032\u0026\u007a\u005a\u0031\u005c\u005e\u0048\u0070\u0061\u0044\u004b\u006d\u0073\u006a\u0045\u003a\u0076\u0020\u003f\u0023\u004b\u0039\u004d\u0045\u0044\u0052\u0045\u002a\u003a\u0024\u0030\u007a\u006d\u0046\u002a\u005a\u002b\u0070\u0043\u005d\u006e\u005b\u0043\u0076\u004e\u002d\u006f\u002d\u0051\u0022\u0060\u0073\u0062\u0037\u0034\u003b\u0043\u0035\u004e\u004f\u003c\u0024\u004d\u0026\u007b\u005e\u005b\u007b\u0062\u005f\u0028\u0069\u005b\u0071\u0032\u007c\u0078\u0037\u0074\u003f\u0063\u004b\u0035\u0041\u002f\u0070\u0038\u006b\u005f\u0054\u0032\u0044\u0022\u0050\u0078\u0038\u0025\u0042\u0031\u0022\u0048\u0052\u002b\u0077\u0071\u0079\u006a\u006b\u002a\u0059\u0034\u0054\u0058\u0078\u003b\u0023\u005b\u0052\u0052\u003b\u0067\u0061\u0060\u005d\u0041\u0037\u003d\u0051\u002b\u002e\u0039\u0078\u003c\u0077\u006e\u0052\u006b\u0022\u0054\u0064\u0037\u004f\u0026\u0051\u0069\u0078\u0040\u0071\u002f\u0072\u0039\u005a\u002b\u0063\u0054\u0060\u0026\u002b\u0058\u007e\u0024\u006a\u0049\u0038\u004a\u0038\u0026\u0033\u005a\u004a\u003a\u0033\u006b\u006e\u006e\u0050\u002b\u0030\u0041\u0020\u005c\u0021\u0057\u002a\u0058\u0069\u005c\u003f\u006a\u0059\u0040\u0053\u0023\u0051\u004f\u0035\u0036\u0037\u006c\u0047\u0048\u0070\u0060\u0057\u007e\u0040\u004a\u004b\u004f\u004c\u0073\u002d\u003b\u0069\u004e\u006e\u0037\u003c\u0062\u005d\u0037\u0077\u0078\u0070\u0044\u002b\u005c\u002d\u0023\u0041\u005b\u0040\u0079\u0029\u005c\u004e\u006f\u005a\u0058\u0063\u0020\u004e\u0075\u003c\u0074\u0051\u0063\u0032\u003b\u0043\u002e\u0079\u0024\u005f\u0049\u0047\u004f\u0053\u0024\u006a\u0036\u0048\u0056\u0053\u002a\u0071\u006c\u0027\u007a\u004b\u0078\u0031\u0056\u0058\u006e\u002d\u005b\u003f\u006f\u0060\u0064\u005b\u0076\u0043\u0062\u003b\u0028\u0037\u0052\u0032\u0067\u0067\u006e\u0052\u0048\u0035\u005c\u0032\u0039\u0072\u0069\u0047\u0026\u0074\u006b\u0028\u006d\u002a\u0020\u0044\u0046\u0055\u007e\u003d\u005d\u0048\u006c\u0041\u006c\u007a\u0058\u0032\u0073\u004f\u0075\u0063\u003d\u002e\u007d\u0051\u004c\u0072\u0033\u003c\u0027\u0025\u0044\u004c\u0069\u0062\u002c\u003f\u0035\u0054\u005b\u0073\u002e\u0078\u0056\u006c\u004c\u007c\u0051\u0026\u0071\u0073\u004b\u0070\u0047\u0049\u004a\u0045\u0032\u0031\u0055\u0078\u002f\u006d\u003a\u004a\u003b\u0065\u0045\u007d\u005a\u0046\u0079\u0031\u0071\u0030\u005b\u004f\u0068\u0070\u004e\u0035\u0073\u0065\u006b\u0028\u0020\u0022\u0063\u0032\u0021\u0044\u002d\u003a\u0054\u004c\u002b\u0079\u0061\u0021\u0060\u0076\u006f\u0028\u003d\u0033\u0056\u0029\u006c\u0065\u0053\u0046\u007e\u0027\u005e\u003b\u0062\u0055\u006c\u0057\u0042\u004f\u0039\u0063\u007a\u006c\u0061\u003c\u0066\u006f\u0072\u006a\u0034\u003f\u0039\u0027\u002b\u007a\u006f\u0059\u0062\u004a\u0021\u006d\u0076\u005e\u0078\u007c\u0072\u0048\u0023\u006b\u0059\u0032\u006f\u0027\u0052\u004e\u005b\u0052\u0045\u005c\u0079\u006a\u0073\u0047\u0056\u0071\u0046\u0038\u0050\u0023\u0060\u0047\u0053\u0043\u0049\u0031\u007d\u0052\u0047\u0031\u0045\u0064\u0051\u0048\u0066\u003b\u0046\u004b\u003c\u0077\u007a\u0024\u0056\u0027\u003d\u002b\u0037\u0056\u0076\u0045\u0071\u007d\u006f\u002b\u006e\u006a\u0031\u0032\u0044\u004b\u003d\u005c\u005e\u0039\u0044\u0052\u0036\u0040\u0079\u0050\u0033\u0026\u0041\u005c\u0028\u0053\u0034\u0031\u0027\u003d\u007a\u0066\u0054\u0041\u0078\u007b\u0021\u005d\u007e\u0042\u0065\u0044\u0034\u0061\u0039\u0077\u002e\u0068\u0029\u007d\u0053\u0068\u006f\u003d\u0037\u0073\u0078\u0072\u002f\u002f\u0051\u0049\u005d\u007c\u007c\u002f\u003c\u0040\u0053\u0072\u006c\u003b\u0041\u002c\u0067\u002d\u0030\u0068\u004c\u0046\u0033\u0045\u003b\u0036\u005c\u005a\u0041\u0064\u0024\u007a\u0072\u0076\u004b\u0025\u004a\u0041\u004a\u0048\u0051\u0032\u004a\u0078\u004d\u0046\u003c\u0068\u0068\u005e\u0047\u004c\u0039\u0061\u0061\u0069\u0049\u0047\u0064\u0024\u006e\u0045\u003a\u0030\u0023\u0048\u005f\u0046\u005a\u0057\u0041\u0071\u0059\u004a\u007a\u003a\u003d\u0041\u006d\u0074\u0057\u0029\u0037\u006f\u0070\u0053\u0028\u0056\u002e\u0079\u0068\u0054\u007b\u005a\u005f\u0077\u0025\u0061\u0065\u0072\u0054\u0074\u0050\u0043\u0079\u0042\u0035\u0026\u005d\u004e\u0031\u0068\u0049\u0047\u002a\u005d\u004e\u007c\u0032\u0034\u002a\u0048\u004f\u0060\u002c\u006f\u007c\u007d\u003b\u0051\u0052\u0035\u0023\u0028\u0040\u0061\u0075\u0030\u0064\u002b\u0028\u003d\u0063\u0036\u002f\u0034\u0039\u0078\u0029\u004f\u0031\u0033\u0039\u003e\u0059\u0022\u0045\u005b\u002a\u003f\u0078\u0073\u0026\u002c\u0072\u0023\u0038\u0068\u007c\u0072\u0065\u0038\u0020\u0065\u007e\u002e\u0045\u007c\u0022\u0072\u0033\u0043\u0060\u003f\u0035\u0048\u0055\u0024\u0025\u0051\u0040\u003b\u0020\u005f\u005a\u006e\u006d\u005b\u007b\u007e\u0034\u0057\u0038\u0050\u0040\u004f\u0025\u004d\u0042\u003b\u005d\u0022\u0056\u007d\u0028\u0052\u0049\u0063\u0031\u004e\u003a\u0042\u006c\u0036\u006a\u0033\u0039\u0057\u0040\u0073\u0055\u0023\u0069\u0059\u0034\u0035\u0028\u0035\u005a\u0059\u005f\u0058\u0079\u004b\u0070\u0025\u004e\u0060\u0059\u0056\u0048\u0023\u0056\u0070\u0056\u0047\u0057\u002a\u0058\u0045\u004e\u0033\u002f\u0023\u0021\u0057\u0033\u006f\u0056\u0065\u003e\u0025\u006d\u0029\u005c\u006f\u0045\u003f\u002a\u0030\u004c\u0047\u005e\u0027\u0079\u0040\u0028\u003f\u0063\u0048\u003b\u007b\u0026\u0071\u0020\u006d\u0068\u002c\u0053\u007d\u0079\u0029\u007a\u0060\u0071\u0042\u005b\u006b\u0072\u0053\u0036\u0058\u0035\u006f\u0027\u0057\u003e\u0077\u0058\u0050\u003a\u0034\u0070\u003c\u0070\u0049\u0074\u0039\u0021\u0037\u0025\u0041\u0030\u0049\u004a\u004c\u003e\u007e\u007b\u007d\u006d\u0063\u0023\u005f\u0076\u0030\u007d\u003a\u005e\u0058\u0037\u0046\u006c\u0035\u0055\u0048\u005b\u0045\u004e\u004e\u003f\u0049\u002d\u006c\u0079\u0063\u006d\u003d\u006e\u0067\u005c\u0023\u0062\u0076\u0022\u0066\u0050\u0069\u0035\u0075\u005e\u0077\u0053\u006a\u0039\u002d\u0054\u003e\u004d\u0031\u002d\u002a\u0057\u0039\u006b\u005d\u005c\u007d\u0064\u0048\u0020\u0046\u0029\u003b\u0055\u002b\u0044\u0071\u0079\u0048\u0044\u0069\u003a\u0051\u0067\u0045\u0039\u0057\u0045\u0078\u0024\u0077\u002d\u007d\u002d\u007b\u0040\u0029\u0050\u005c\u0055\u006c\u0069\u0063\u0044\u0048\u0049\u0046\u005d\u0073\u0033\u002f\u0049\u004e\u0079\u002d\u0041\u0043\u0038\u002f\u0034\u0048\u0075\u004c\u0022\u0074\u0041\u0074\u0063\u0067\u0030\u002c\u0079\u0074\u0055\u0050\u006a\u002c\u0027\u0035\u0028\u0021\u007e\u0049\u0069\u0048\u002c\u007c\u005e\u0029\u0036\u005f\u003d\u005b\u0022\u0054\u0068\u004f\u005e\u0078\u003a\u004e\u0075\u004d\u0022\u006f\u005b\u0055\u0037\u004d\u0031\u004f\u0071\u0061\u0077\u005e\u0052\u003b\u0072\u0078\u007d\u005a\u0026\u005c\u0054\u0055\u0046\u0034\u003d\u0056\u003b\u0040\u0069\u005f\u005a\u0031\u0037\u005e\u003b\u0022\u0058\u0064\u0020\u0076\u0070\u005a\u0026\u005f\u0068\u005b\u006c\u006c\u003a\u0035\u005e\u0023\u0024\u0062\u0028\u005f\u006b\u006b\u003e\u0057\u0047\u0045\u005c\u0072\u0050\u002e\u0035\u006b\u004c\u0027\u004e\u006d\u0055\u0026\u003f\u0053\u005d\u006b\u0021\u0078\u005e\u005d\u007c\u006a\u004f\u0026\u0038\u0034\u0060\u0023\u003d\u003a\u0030\u006a\u0079\u0056\u0060\u0021\u004e\u0031\u002f\u0077\u0038\u006b\u0071\u0028\u0045\u003a\u0076\u007c\u0037\u0065\u0035\u007d\u0048\u007e\u0035\u0076\u002a\u0043\u003d\u007e\u0047\u0060\u0054\u0041\u0041\u0033\u0035\u0032\u0064\u0023\u0051\u0040\u0063\u0043\u006a\u006f\u0036\u0034\u0056\u003a\u003b\u0051\u0042\u0048\u0071\u0059\u004a\u0033\u0037\u0025\u005c\u0075\u0023\u0039\u005c\u0040\u005e\u0033\u006c\u002a\u0038\u0027\u0044\u0068\u0046\u0062\u007b\u005f\u0029\u0032\u0024\u0062\u0033\u006c\u0058\u0068\u003a\u0038\u006d\u0062\u004b\u004b\u005a\u0034\u003a\u002d\u0060\u006c\u0067\u0058\u0071\u004a\u006f\u003f\u0030\u003a\u0023\u0034\u007d\u004f\u0025\u0027\u007a\u003d\u0025\u002c\u007b\u0020\u0078\u0069\u0039\u007b\u006d\u0026\u003e\u0067\u0070\u0030\u004e\u005b\u004b\u005d\u0042\u0042\u0062\u0046\u002f\u0061\u0034\u0022\u0065\u0069\u0040\u0051\u0031\u004f\u0055\u002f\u0078\u0071\u005c\u003f\u0075\u0030\u006d\u0035\u0056\u0073\u0069\u006c\u002a\u0020\u0020\u0073\u0049\u003f\u0040\u002f\u0035\u003c\u0060\u0023\u0063\u003e\u0049\u0022\u004f\u006b\u002e\u006c\u0065\u0063\u007d\u006b\u005b\u004c\u007b\u0072\u003a\u0050\u0065\u0078\u002d\u0078\u0058\u003f\u0042\u0066\u0022\u0046\u0076\u005a\u0079\u002f\u0042\u005f\u007e\u0060\u004b\u0047\u0044\u0053\u0034\u003e\u003b\u006a\u004a\u0022\u003c\u0056\u0035\u004a\u005a\u007c\u007a\u0077\u0056\u007b\u003b\u0058\u005e\u006f\u0058\u0041\u004f\u0069\u002d\u0070\u0039\u0028\u0076\u004d\u0039\u0079\u004c\u007a\u0071\u0043\u0027\u007c\u006b\u002f\u003f\u0052\u005b\u0036\u005d\u0073\u0038\u002a\u0047\u006a\u0022\u007b\u0040\u002c\u003a\u003d\u007b\u007d\u0069\u0036\u004f\u0064\u005c\u0072\u0033\u0066\u0049\u007d\u0023\u002a\u0045\u002b\u0062\u006f\u0059\u0052\u0024\u006a\u0027\u0072\u0050\u0032\u006e\u0053\u004e\u0033\u004d\u0065\u007d\u0076\u0067\u0073\u0032\u0024\u0043\u0039\u0027\u005b\u002b\u0065\u0069\u0045\u0052\u006d\u0034\u005d\u0040\u007c\u002d\u0058\u0074\u004f\u003a\u003c\u002b\u0036\u0038\u005b\u0032\u0055\u0046\u0054\u0079\u006c\u005d\u0046\u006c\u003e\u0032\u006f\u005f\u0047\u005b\u0028\u0029\u0077\u0078\u004a\u0029\u0024\u0048\u007e\u006c\u004e\u004c\u0048\u0078\u0037\u0027\u0040\u0030\u0072\u0077\u0078\u002d\u0023\u004e\u0057\u0062\u0024\u0072\u0060\u003f\u0073\u005b\u0063\u0068\u004a\u0052\u0037\u007b\u007a\u005d\u0077\u0036\u0050\u0043\u0027\u0056\u003b\u0057\u006d\u007e\u0044\u0028\u0027\u0052\u007a\u0044\u0066\u0047\u0021\u0033\u0062\u0062\u004b\u0039\u0062\u0036\u006e\u0059\u0076\u0044\u0041\u0042\u0044\u006b\u003e\u006c\u0074\u0040\u004d\u0077\u0056\u0077\u0044\u005a\u003e\u007d\u0065\u0061\u0036\u005c\u0075\u0051\u003c\u0076\u0024\u0055\u0060\u005f\u0078\u0029\u006c\u007b\u0054\u006a\u006d\u0056\u006a\u003d\u005f\u0037\u006b\u007d\u0064\u0074\u002a\u002e\u0048\u0027\u0058\u0042\u0071\u004e\u0026\u0054\u0067\u0029\u0034\u0062\u007d\u006f\u0054\u0036\u0057\u0065\u002d\u007b\u0048\u0021\u002e\u0074\u0046\u005a\u002f\u0052\u0027\u0073\u0063\u0079\u003e\u0058\u0055\u0059\u0043\u004e\u007b\u0068\u0069\u0055\u003b\u005c\u0034\u0046\u0033\u006c\u0069\u0065\u003f\u0068\u0059\u003d\u0063\u0021\u006d\u002d\u0029\u005b\u006c\u0071\u0077\u003f\u0029\u0022\u003a\u002b\u0039\u0068\u002e\u0031\u0027\u0039\u0078\u0054\u004a\u0033\u0076\u0064\u0050\u007b\u002a\u0047\u002e\u0061\u003f\u003b\u0069\u003d\u003c\u002f\u0034\u005d\u003e\u006c\u004a\u0021\u0062\u007b\u003f\u0030\u0022\u0062\u004b\u0035\u004a\u006b\u003b\u0079\u002a\u0041\u0025\u003f\u005d\u0023\u003c\u0031\u0038\u0074\u003c\u0028\u0077\u006a\u0079\u007e\u0069\u003b\u006c\u0052\u0058\u0065\u0068\u004f\u0038\u0052\u0049\u007a\u0059\u0054\u0042\u0049\u0047\u0032\u003f\u0050\u006e\u0044\u0049\u006b\u0047\u002c\u005e\u002e\u0058\u0078\u0044\u0041\u0020\u0064\u006c\u0034\u0063\u0020\u0066\u0021\u006c\u002a\u006b\u004b\u0075\u006d\u0074\u002a\u0053\u0053\u005d\u005a\u004e\u0044\u002c\u0026\u007c\u0078\u0039\u002c\u0032\u0071\u004f\u0023\u004e\u0027\u004a\u004a\u0023\u0050\u006f\u0042\u002f\u0039\u0071\u004f\u0071\u0055\u0032\u0079\u004a\u0078\u0020\u0023\u003c\u0060\u004a\u0056\u0042\u0055\u004f\u0042\u0076\u0033\u007b\u003e\u003d\u0058\u0030\u002c\u004d\u0058\u005d\u0035\u0073\u004f\u002a\u0040\u0055\u003a\u0071\u003c\u0072\u007c\u0072\u0037\u0031\u0022\u0031\u0045\u0044\u0066\u0037\u0038\u0076\u0075\u0028\u0056\u004f\u0059\u0036\u0024\u006d\u0051\u006d\u003e\u0078\u0047\u003d\u004f\u0055\u004e\u007b\u0065\u0049\u005d\u003e\u0024\u005d\u005a\u007d\u0078\u0023\u0072\u0076\u0032\u0053\u002e\u0070\u0073\u0034\u0070\u0037\u006a\u005f\u005e\u0054\u0056\u007a\u0045\u0045\u006b\u0057\u0060\u0079\u0029\u005e\u0034\u0025\u0071\u0054\u0042\u0037\u003a\u0051\u003e\u0061\u0069\u0058\u006d\u005c\u0028\u002c\u0036\u004c\u0064\u003c\u007d\u0033\u0048\u0054\u0028\u006f\u0054\u0078\u003b\u0023\u0036\u002e\u003e\u0025\u0077\u006a\u0067\u0042\u0047\u0031\u005d\u006b\u0050\u007a\u0046\u004f\u005b\u006a\u007d\u002e\u002f\u006d\u004b\u0076\u0020\u006c\u0069\u0035\u003f\u0065\u005c\u0023\u0053\u0033\u0068\u0033\u0030\u003f\u0044\u004c\u0021\u0060\u003a\u007a\u003a\u0044\u004c\u0042\u0075\u0047\u0059\u0079\u0033\u0067\u0049\u0024\u0034\u0075\u0024\u0020\u0033\u0051\u006b\u004c\u0046\u0027\u0058\u0039\u005e\u0072\u005c\u0074\u0044\u0021\u004b\u0059\u0057\u006c\u007d\u0063\u005d\u0065\u005c\u0029\u0034\u0027\u0039\u0046\u007e\u002f\u003d\u0028\u007c\u0071\u006c\u004a\u0044\u0028\u0055\u004c\u002b\u0052\u0040\u004a\u0065\u0073\u0068\u0041\u0076\u0051\u0040\u003c\u0035\u0049\u0040\u0052\u0036\u0065\u004c\u004e\u005d\u004d\u0034\u0027\u0076\u0035\u0043\u004f\u0071\u0054\u0077\u004d\u003e\u005c\u0045\u0053\u004d\u0052\u0073\u007e\u0048\u004f\u002d\u007d\u0041\u0032\u0071\u0061\u003a\u0020\u0031\u004f\u006b\u004e\u0033\u0064\u0046\u006b\u0038\u0079\u0042\u0061\u0074\u0040\u0041\u004f\u0047\u0079\u0060\u0033\u004f\u0031\u0036\u0052\u0075\u004c\u0032\u002d\u0038\u005b\u0041\u006c\u0051\u002c\u0044\u002a\u006e\u0077\u0041\u0058\u0062\u0034\u0079\u0037\u0058\u0048\u0036\u0062\u0058\u0025\u007a\u0071\u0059\u006b\u0054\u0041\u0065\u0035\u0038\u0057\u007b\u0077\u0055\u0068\u0051\u0069\u0029\u0069\u006a\u004e\u0079\u0030\u0055\u0059\u0076\u004e\u0055\u0079\u005c\u0062\u002c\u002c\u006e\u007a\u0023\u002b\u0075\u006e\u0044\u0067\u0056\u003a\u0065\u0079\u0072\u006a\u0020\u002f\u004f\u0045\u0048\u0065\u0068\u005c\u0041\u0021\u0027\u003f\u0022\u004b\u0022\u0060\u0065\u0023\u0069\u0076\u003d\u0065\u004d\u0056\u0036\u0055\u0042\u0023\u0069\u0028\u007b\u003d\u006c\u0035\u0026\u005a\u002b\u005c\u004f\u0065\u0070\u0032\u0051\u0069\u006e\u0054\u006e\u0041\u0040\u005e\u007a\u0023\u007d\u006c\u0049\u005b\u006d\u0023\u006b\u0042\u0071\u0046\u006d\u0040\u0074\u0028\u0033\u007d\u0032\u0077\u0035\u0045\u0072\u0044\u0071\u003a\u0065\u003a\u007d\u0031\u0042\u0051\u0046\u005c\u0068\u007e\u0034\u0067\u0047\u002e\u003d\u0043\u005b\u0022\u0056\u0057\u0070\u0064\u003e\u007b\u004d\u0038\u0071\u0063\u0031\u0075\u005a\u0046\u002a\u0060\u006f\u0040\u0047\u0042\u0048\u002c\u0038\u0076\u004f\u0051\u0040\u0038\u004a\u004c\u0061\u0024\u0030\u006d\u0052\u0020\u005a\u0057\u0023\u002f\u0050\u0055\u007a\u0051\u0036\u004a\u0060\u0057\u0037\u005e\u006f\u0044\u0061\u005f\u0079\u006d\u0075\u005e\u0045\u0075\u0065\u0037\u0030\u004d\u0070\u002a\u002c\u0039\u0064\u0075\u005a\u0029\u007c\u0075\u004a\u004c\u003b\u0050\u003a\u0048\u0055\u003d\u003e\u0037\u0039\u0063\u0074\u002f\u0078\u0023\u0020\u0060\u0079\u0037\u0078\u0067\u007a\u005e\u0060\u004b\u0032\u0070\u0020\u002c\u002f\u0033\u0066\u007a\u007a\u006b\u007e\u0056\u0054\u0065\u0027\u006b\u0041\u002f\u006c\u0068\u0048\u0060\u0040\u0047\u002a\u0051\u0066\u0063\u0060\u005e\u0068\u0078\u0027\u003f\u0061\u0029\u0067\u0074\u005a\u0028\u0072\u004e\u006d\u006b\u005c\u0052\u0038\u0075\u0037\u0022\u004c\u0056\u005d\u0034\u0043\u0045\u005a\u0050\u0078\u0060\u0032\u0025\u005a\u0044\u0073\u0064\u0027\u002a\u0047\u005b\u0036\u006e\u003b\u0071\u0040\u005b\u005f\u0038\u0042\u0051\u003f\u0020\u006e\u0021\u0031\u0048\u0038\u002c\u005b\u0041\u0033\u0046\u0032\u0059\u007d\u0027\u0030\u005a\u006f\u003b\u005a\u0033\u007a\u0062\u0060